{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Each tile's footprint, one panel per year it was flown.",
  "facet": {
    "column": {
      "field": "year",
      "type": "nominal",
      "title": "Year"
    }
  },
  "spec": {
    "width": 200,
    "height": 200,
    "mark": {
      "type": "geoshape",
      "stroke": "white",
      "strokeWidth": 1
    },
    "encoding": {
      "color": {
        "field": "year",
        "type": "nominal",
        "title": "Year"
      },
      "tooltip": [
        {
          "field": "tile",
          "type": "nominal"
        },
        {
          "field": "year",
          "type": "nominal"
        },
        {
          "field": "crs",
          "type": "nominal"
        }
      ]
    }
  }
}
